"""
Test the assignments to the properties and to the items of the lists
in the verification functions.

The Python SDK uses the native assignments. We still generate the tests so that
the clients can compare the behavior against the other SDKs.
"""


# This code has been automatically generated by aas-core-codegen.
# Do NOT edit or append.


# pylint: disable=missing-docstring


import unittest

import dummy.types as aas_types
import dummy.verification as aas_verification


class TestAssignmentTargets(unittest.TestCase):
    def test_set_text(self) -> None:
        item = aas_types.Item("a", ["b"])
        aas_verification.set_text(item, "x")
        self.assertEqual("x", item.text)

    def test_set_maybe_text(self) -> None:
        item = aas_types.Item("a", [])
        aas_verification.set_maybe_text(item, "x")
        self.assertEqual("x", item.maybe_text)

    def test_copy_maybe_text_and_set_maybe_kind(self) -> None:
        item = aas_types.Item("a", [], maybe_text="old")
        other = aas_types.Item("b", [])
        aas_verification.copy_maybe_text_and_set_maybe_kind(item, other)
        self.assertIsNone(item.maybe_text)
        self.assertEqual(aas_types.Kind.ALPHA, item.maybe_kind)

    def test_set_text_through_alias(self) -> None:
        item = aas_types.Item("a", [])
        aas_verification.set_text_through_alias(item, "x")
        self.assertEqual("x", item.text)

    def test_set_texts(self) -> None:
        item = aas_types.Item("a", ["b"])
        texts = ["x", "y"]
        aas_verification.set_texts(item, texts)
        self.assertIs(texts, item.texts)

    def test_set_first_and_last_text(self) -> None:
        item = aas_types.Item("a", ["a", "b", "c"])
        aas_verification.set_first_and_last_text(item, "x")
        self.assertEqual(["x", "b", "x"], item.texts)

    def test_set_text_through_list_alias(self) -> None:
        item = aas_types.Item("a", ["a", "b", "c"])
        aas_verification.set_text_through_list_alias(item, "x")
        self.assertEqual(["a", "x", "c"], item.texts)

    def test_set_numbers(self) -> None:
        numbers = [1, 2, 3, 4]
        aas_verification.set_numbers(numbers, 10)
        self.assertEqual([10, 2, 5, 4], numbers)

    def test_set_numbers_out_of_range(self) -> None:
        with self.assertRaises(IndexError):
            aas_verification.set_numbers([1], 10)

    def test_set_nested_text(self) -> None:
        items = [aas_types.Item("a", ["a", "b"]), aas_types.Item("b", ["c"])]
        aas_verification.set_nested_text(items, "x")
        self.assertEqual(["a", "x"], items[0].texts)
        self.assertEqual("x", items[1].text)

    def test_replace_first_item(self) -> None:
        items = [aas_types.Item("a", []), aas_types.Item("b", [])]
        item = aas_types.Item("c", [])
        aas_verification.replace_first_item(items, item)
        self.assertIs(item, items[0])
        self.assertEqual(2, len(items))

    def test_set_texts_in_loops(self) -> None:
        items = [aas_types.Item("a", ["a"]), aas_types.Item("b", ["b", "c"])]
        aas_verification.set_texts_in_loops(items, "x")
        for item in items:
            self.assertEqual("x", item.text)
            self.assertEqual("x", item.texts[0])


if __name__ == "__main__":
    unittest.main()


